# ---------------------------------------------------------------- vínculos evidencia <-> evento/aviso
# `eventos_vinculados` de cada evidencia se DERIVA de los eventos (columna `evidencias`) y avisos
# (columna `evidencia`) que la citan, para que los vínculos sean siempre bidireccionales.
# Sin citas se conserva el texto libre original (p. ej. «ninguno (URL hallada descartada)»).
_EVD_RE = re.compile(r"EVD-\d+")
_LINK_RE = re.compile(r"\b(?:EV-\d{8}-\d{3}|AV-\d{3})\b")
_cita = {}
for r in E:
    for i in _EVD_RE.findall(r[EH.index("evidencias")]):
        _cita.setdefault(i, []).append(r[0])
for r in A:
    for i in _EVD_RE.findall(r[AH.index("evidencia")]):
        _cita.setdefault(i, []).append(r[0])
NOTAS_VINCULO = {
 "EVD-019": "citada por EV-20261013-001, EV-20261013-003 y EV-20261013-004 solo como contexto: cuerpo inaccesible, no sostiene hechos por sí sola",
 "EVD-047": "antes vinculada también a EV-20261010-001 (Alvear), que no la cita: nota no localizada, no se usa para ese evento",
}
_ivin, _ilim = VH.index("eventos_vinculados"), VH.index("limitaciones")
_ids_v = {r[0] for r in V}
_huerfanas = sorted(set(_cita) - _ids_v)
assert not _huerfanas, ("evidencias citadas que no existen en evidencias.csv", _huerfanas)
for r in V:
    nuevo = ";".join(dict.fromkeys(_cita.get(r[0], [])))
    if nuevo and r[_ivin] != nuevo:
        print("vínculo derivado", r[0], ":", repr(r[_ivin]), "->", repr(nuevo))
        r[_ivin] = nuevo
    if r[0] in NOTAS_VINCULO and NOTAS_VINCULO[r[0]] not in r[_ilim]:
        r[_ilim] = (r[_ilim] + "; " if r[_ilim] else "") + NOTAS_VINCULO[r[0]]
# Aserción: ningún vínculo unilateral (evidencia -> evento/aviso que no la cita, o al revés).
_unilaterales = [(r[0], sorted(set(_LINK_RE.findall(r[_ivin])) ^ set(_cita.get(r[0], [])))) for r in V
                 if set(_LINK_RE.findall(r[_ivin])) != set(_cita.get(r[0], []))]
assert not _unilaterales, ("vínculos evidencia<->evento/aviso unilaterales", _unilaterales)
w("evidencias.csv", VH, V)

